{{(() => {
  const ratings = [
    Rating18.value,
		Rating19.value,
		Rating20.value,
		Rating22.value,
    Rating23.value,
		Rating24.value,
		Rating25.value,
		Rating26.value,
		Rating27.value,
    Rating28.value
  ];

  const hasInvalidRating = ratings.some(r => r === null || r === 0);

  if (hasInvalidRating) {
    return "OBIETTIVO DELLA SETTIMANA: RISPETTO DELL'ORDINE ORGANIZZATIVO E VOLONTÀ DI APPRENDERE";
  }

  const somma = ratings.reduce((acc, val) => acc + val, 0);

  return somma === 0 ? "" : (somma === 30 ? "OBIETTIVO DELLA SETTIMANA RAGGIUNTO: RISPETTO DELL'ORDINE ORGANIZZATIVO E VOLONTÀ DI APPRENDERE" : "OBIETTIVO DELLA SETTIMANA NON RAGGIUNTO: RISPETTO DELL'ORDINE ORGANIZZATIVO E VOLONTÀ DI APPRENDERE");
})()
}}

